function submit(form){
 requireAccess(true);const d=getData(),e=currentEntry(d);
 if(form.id==='fin-series-form'){if(e.kind!=='series')throw Error('Geen serie geselecteerd.');Object.assign(e,{planned:C.cents(read('fin-series-planned')),fee:C.cents(read('fin-series-fee')),feeAow:C.cents(read('fin-series-aow')),looseFee:C.cents(read('fin-series-loose')),note:read('fin-series-note'),configured:true,migrationNotice:false});save(d);}
 if(form.id==='fin-water-form'){FinanceWaters.upsert(d,{name:read('fin-water-name'),location:read('fin-water-location')});save(d);}
 if(form.id==='fin-budget-form'){d.finance.years[state.year]={budget:C.cents(read('fin-budget')),carry:C.cents(read('fin-carry')),configured:true};save(d);state.view='overview';}
 if(form.id==='fin-entry-form'){
  const title=read('fin-title').trim();if(!title)throw Error('Vul een omschrijving in.');const date=read('fin-date')?C.date(read('fin-date')):e.kind==='expense'?'':C.date('');e.year=Number(date.slice(0,4)||e.year||state.year);if(e.status==='settled'&&date.slice(0,4)!==e.date.slice(0,4))throw Error('Heropen de post voordat je hem naar een ander jaar verplaatst.');
  Object.assign(e,{title,date,planned:C.cents(read('fin-planned')),note:read('fin-note'),configured:true});if(e.kind==='expense')e.category=read('fin-category').trim()||'Overig';else e.fee=C.cents(read('fin-fee'));
  const r=d.roosterItems.find(r=>r.id===e.agendaId);if(r){r.titel=title;r.datum=date;}for(const wid of C.matchIds(d,e.matchId)){const w=d.wedstrijden.find(w=>w.id===wid);if(w){w.naam=title;w.datum=date;}}save(d);
 }
 if(form.id==='fin-settle-form'){if(e.status==='cancelled')throw Error('Heropen eerst deze post.');e.payout=C.cents(read('fin-payout'));e.status='settled';save(d);}
 if(form.id==='fin-user-form'){if(!isHoofdAdmin())throw Error('Alleen de hoofdbeheerder beheert accounts.');const name=read('fin-user-name').trim(),code=read('fin-user-code').trim();if(!name||code.length<4)throw Error('Vul een naam en een code van minimaal vier tekens in.');d.admins.push({id:uid(),naam:name,code,rol:'admin',actief:true,financeOnly:true,financeAccess:read('fin-user-right')});save(d);if(state.view!=='rights')renderBeheer();}
 render();showAppNotice('Opgeslagen.');
}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-fin]');if(el){ev.preventDefault();Promise.resolve(action(el.dataset.fin,el)).catch(noticeError);}});
document.addEventListener('change',ev=>{if(ev.target.matches('[data-fin-change],[data-water-field],#fin-import-file,#fin-attachment-file'))Promise.resolve(change(ev.target)).catch(err=>{noticeError(err);if(['paid','series-mode'].includes(ev.target.dataset.finChange)){if(ev.target.closest('.fin-pay-panel'))mountPayments();else render();}});});
document.addEventListener('submit',ev=>{if(ev.target.id.startsWith('fin-')){ev.preventDefault();try{submit(ev.target);}catch(err){noticeError(err);}}});
