exporteerBackup=function(){if(!isHoofdAdmin()){showAppNotice('Alleen de hoofdbeheerder kan een volledige back-up maken.','warn');return;}const data=getData(),meta=maakBackupMetadata(data);triggerBlobDownload(new Blob([JSON.stringify({meta,data},null,2)],{type:'application/json'}),'HSV_GHW_backup_'+new Date().toISOString().slice(0,10)+'.json');showAppNotice('Back-up inclusief financiën en bijlagen gedownload.');};
const oldRestore=bevestigHerstel;bevestigHerstel=function(){if(!isHoofdAdmin())return;oldRestore();doLogout();};
