const oldPlanning=getRoosterPlanningItems;getRoosterPlanningItems=function(d){return oldPlanning(d).map(r=>{const e=d.finance?.entries.find(e=>e.agendaId===r.id);return e?.status==='cancelled'?{...r,titel:'Afgelast · '+r.titel}:r;});};
const oldStart=maakWedstrijdVanRoosterItem;maakWedstrijdVanRoosterItem=function(id){const e=getData().finance.entries.find(e=>e.agendaId===id);if(e?.status==='cancelled'){showAppNotice('Deze wedstrijd is afgelast. Heropen eerst de financiële post.','warn');return;}oldStart(id);};
